import axios from 'axios';

const BANDE_COMMANDE_API_BASE_URL = "http://localhost:8080/api/v1/bande-commande";

class BandeCommandeService {
    getAllBandeCommandes(entite, typeMarche, filter) {
        return axios.get(BANDE_COMMANDE_API_BASE_URL, {
            params: { entite, typeMarche, filter }
        });
    }

    getDashboard(entite) {
        return axios.get(`${BANDE_COMMANDE_API_BASE_URL}/dashboard`, {
            params: { entite }
        });
    }

    deleteBandeCommande(id) {
        return axios.delete(`${BANDE_COMMANDE_API_BASE_URL}/${id}`);
    }
}

export default new BandeCommandeService();
